      "content": "{\n  \"name\": \"dsh-vision-router\",\n  \"version\": \"3.1.0\",\n  \"description\": \"Eyes for text-only DeepSeek Harness agents: built-in free vision chain + pixel-level tools. Remote vision providers, including the default free fallback, receive image content unless strict local-only use is configured.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/ysr666/dsh-vision-router.git\"\n  },\n  \"homepage\": \"https://github.com/ysr666/dsh-vision-router\",\n  \"type\": \"module\",\n  \"main\": \"lib/public-entry.js\",\n  \"bin\": {\n    \"dsh-vision-router\": \"./lib/doctor-cli-p0.js\"\n  },\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/public-entry.d.ts\",\n      \"default\": \"./lib/public-entry.js\"\n    },\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\"\n  },\n  \"files\": [\n    \"LICENSE\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"assets\",\n    \"cordis.patch.yml\",\n    \"docs\",\n    \"entry.js\",\n    \"index.js\",\n    \"lib\",\n    \"presets\"\n  ],\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.2.0-rc.2 <0.3.0-0\"\n  },\n  \"packageManager\": \"pnpm@11.20.0\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"vision\",\n    \"vision-tools\",\n    \"multimodal\",\n    \"openrouter\",\n    \"image\",\n    \"ocr\",\n    \"screenshot\",\n    \"plugin\"\n  ],\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \">=3.18.0\",\n    \"potrace\": \"^2.1.8\",\n    \"puppeteer-core\": \"^25.16.0\",\n    \"undici\": \"^7.30.1\",\n    \"zod\": \"^4.6.6\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-anonymous-user-id\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.2.0-rc.2 <0.3.0-0\",\n    \"@deepseek-ai/dsh-llm-deepseek\": \">=0.1.5-rc.1 <0.2.0-0 || >=0.2.0-rc.2 <0.3.0-0\",\n    \"sharp\": \">=0.35.3 <1\"